using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;using UnityEngine.Rendering.Universal;
public static class Cave202Diagnostic{
 [Serializable]class Row{public string id,mode,light;public float before,after;public bool exact;}
 [Serializable]class Result{public bool pass;public Row[] rows;public string scope;}
 static void Check(bool b,string m){if(!b)throw new Exception(m);}
 public static void Run(){string root=Path.GetFullPath(Path.Combine(Application.dataPath,"..")),outDir=Path.Combine(root,"Evidence202Diagnostic");Directory.CreateDirectory(outDir);try{
  EditorSceneManager.NewScene(NewSceneSetup.EmptyScene,NewSceneMode.Single);Shader.SetGlobalVector("_TDPineWind",Vector4.zero);RenderSettings.ambientMode=AmbientMode.Flat;RenderSettings.ambientLight=Color.black;RenderSettings.ambientIntensity=0;RenderSettings.skybox=null;RenderSettings.reflectionIntensity=0;
  var cam=new GameObject("offscreen").AddComponent<Camera>();cam.clearFlags=CameraClearFlags.SolidColor;cam.backgroundColor=Color.black;cam.GetUniversalAdditionalCameraData().renderPostProcessing=false;
  var light=new GameObject("local").AddComponent<Light>();light.color=new Color(1,.65f,.3f);light.intensity=4;light.range=6;light.spotAngle=70;light.innerSpotAngle=45;
  var sun=new GameObject("sun").AddComponent<Light>();sun.type=LightType.Directional;sun.transform.rotation=Quaternion.Euler(45,30,0);sun.intensity=1;
  var blocker=GameObject.CreatePrimitive(PrimitiveType.Cube);blocker.GetComponent<Renderer>().shadowCastingMode=ShadowCastingMode.ShadowsOnly;var rows=new List<Row>();
  foreach(int mode in new[]{0,2}){
   var rp=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<UniversalRenderPipelineAsset>("Assets/Settings/PC_RPAsset.asset"));var rd=UnityEngine.Object.Instantiate(AssetDatabase.LoadAssetAtPath<UniversalRendererData>("Assets/Settings/PC_Renderer.asset"));var sr=new SerializedObject(rd);sr.FindProperty("m_RenderingMode").intValue=mode;sr.ApplyModifiedPropertiesWithoutUndo();var sp=new SerializedObject(rp);sp.FindProperty("m_RendererDataList").GetArrayElementAtIndex(0).objectReferenceValue=rd;sp.FindProperty("m_AdditionalLightsRenderingMode").intValue=1;sp.ApplyModifiedPropertiesWithoutUndo();GraphicsSettings.defaultRenderPipeline=rp;QualitySettings.renderPipeline=rp;
   foreach(string id in new[]{"cnd001","cnd014","cnd020"}){
    var prefab=AssetDatabase.LoadAssetAtPath<GameObject>("Assets/MapSharedPropsGenerated/Pilot 17/"+id+".prefab");Check(prefab,"formal baseline "+id);var obj=(GameObject)PrefabUtility.InstantiatePrefab(prefab);var renderer=obj.GetComponent<Renderer>();var mat=new Material(renderer.sharedMaterial);renderer.sharedMaterial=mat;Check(!mat.IsKeywordEnabled("SMALL_PROP_LOCAL_LIGHTS"),"baseline missing keyword");
    var target=renderer.bounds.center;float size=Mathf.Max(renderer.bounds.size.x,renderer.bounds.size.y,renderer.bounds.size.z);cam.transform.position=target+new Vector3(1.3f,1.2f,-2)*Mathf.Max(size,.5f);cam.transform.LookAt(target);cam.fieldOfView=38;Vector3 dir=new Vector3(-.6f,1,-.7f).normalized;
    foreach(string kind in new[]{"off","ambient","day","point","far","spot","spotOutside","pointShadow","spotShadow"}){
     sun.enabled=kind=="day";RenderSettings.ambientLight=kind=="ambient"?new Color(.15f,.15f,.15f):Color.black;RenderSettings.ambientIntensity=kind=="ambient"?1:0;light.enabled=kind!="off"&&kind!="ambient"&&kind!="day";light.type=kind.StartsWith("spot")?LightType.Spot:LightType.Point;light.transform.position=target+dir*(kind=="far"?5f:Mathf.Max(1.8f,size*1.7f));light.transform.LookAt(target);if(kind=="spotOutside")light.transform.Rotate(0,100,0,Space.World);bool shadow=kind.EndsWith("Shadow");light.shadows=shadow?LightShadows.Hard:LightShadows.None;blocker.SetActive(shadow);blocker.transform.position=Vector3.Lerp(target,light.transform.position,.5f);blocker.transform.rotation=Quaternion.LookRotation(light.transform.position-target);blocker.transform.localScale=new Vector3(size*3,size*3,.1f);
     float[] mean=new float[2];byte[][] png=new byte[2][];for(int stage=0;stage<2;stage++){if(stage==0)mat.DisableKeyword("SMALL_PROP_LOCAL_LIGHTS");else mat.EnableKeyword("SMALL_PROP_LOCAL_LIGHTS");var im=Shared117Review.Image(cam,480,360);png[stage]=im.EncodeToPNG();mean[stage]=im.GetPixels().Average(c=>(c.r+c.g+c.b)/3);if(mode==2&&(kind=="point"||kind=="spotShadow"))File.WriteAllBytes(Path.Combine(outDir,id+"-"+kind+"-"+stage+".png"),png[stage]);UnityEngine.Object.DestroyImmediate(im);}
     bool exact=png[0].SequenceEqual(png[1]);if(kind=="off"||kind=="ambient"||kind=="day"||kind=="spotOutside")Check(exact,"unchanged "+id+kind);if(kind=="point"||kind=="spot")Check(mean[1]>mean[0]+.0001f,"local response "+id+kind);rows.Add(new Row{id=id,mode=mode.ToString(),light=kind,before=mean[0],after=mean[1],exact=exact});
    }
    float Gain(string k){var q=rows.Last(x=>x.id==id&&x.mode==mode.ToString()&&x.light==k);return q.after-q.before;}Check(Gain("far")<Gain("point")*.8f,"distance");Check(Gain("pointShadow")<Gain("point")*.3f&&Gain("spotShadow")<Gain("spot")*.3f,"shadow");UnityEngine.Object.DestroyImmediate(mat);UnityEngine.Object.DestroyImmediate(obj);
   }
  }
  File.WriteAllText(Path.Combine(outDir,"checks.json"),JsonUtility.ToJson(new Result{pass=true,rows=rows.ToArray(),scope="Existing formal baseline cnd001/014/020; only cloned material keyword toggled in memory; no product/source/assets saved"},true));EditorApplication.Exit(0);
 }catch(Exception e){File.WriteAllText(Path.Combine(outDir,"error.txt"),e.ToString());EditorApplication.Exit(1);}}
}
